const Move=struct{row:usize,col:usize,degree:usize};
const DX=[_]i32{1,2,2,1,-1,-2,-2,-1};const DY=[_]i32{-2,-1,1,2,2,1,-1,-2};
fn countNeighbors(board:*[64]i32,row:i32,col:i32)usize{var n:usize=0;for(0..8)|i|{const r=row+DY[i];const c=col+DX[i];if(r>=0 and r<8 and c>=0 and c<8 and board[@intCast(r*8+c)]==0)n+=1;}return n;}
fn neighbors(board:*[64]i32,row:i32,col:i32,out:*[8]Move)usize{var n:usize=0;for(0..8)|i|{const r=row+DY[i];const c=col+DX[i];if(r>=0 and r<8 and c>=0 and c<8 and board[@intCast(r*8+c)]==0){out[n]=.{.row=@intCast(r),.col=@intCast(c),.degree=countNeighbors(board,r,c)};n+=1;}}var i:usize=1;while(i<n):(i+=1){const value=out[i];var j=i;while(j>0 and out[j-1].degree>value.degree){out[j]=out[j-1];j-=1;}out[j]=value;}return n;}
fn orphan(board:*[64]i32,count:i32,row:i32,col:i32)bool{if(count<63){var moves:[8]Move=undefined;const n=neighbors(board,row,col,&moves);for(0..n)|i|{if(countNeighbors(board,@intCast(moves[i].row),@intCast(moves[i].col))==0)return true;}}return false;}
fn solve(board:*[64]i32,row:i32,col:i32,count:i32)bool{if(count>64)return true;var moves:[8]Move=undefined;const n=neighbors(board,row,col,&moves);if(n==0 and count!=64)return false;for(0..n)|i|{const m=moves[i];board[m.row*8+m.col]=count;if(!orphan(board,count,@intCast(m.row),@intCast(m.col)) and solve(board,@intCast(m.row),@intCast(m.col),count+1))return true;board[m.row*8+m.col]=0;}return false;}
fn put(out:[*c]u8,index:usize,value:i64)void{const bits:u64=@bitCast(value);for(0..8)|b|out[index*8+b]=@truncate(bits>>@intCast(8*b));}
pub export fn knights_tour_warnsdorff_open(_input:[*c]const i64,length:usize,output:[*c]u8,capacity:usize)i64{if(length!=0)return -1;if(output==null or capacity<512)return -2;var board=[_]i32{0}**64;board[0]=1;if(!solve(&board,0,0,2))return -1;var path=[_]i64{0}**64;for(0..8)|r|for(0..8)|c|path[@intCast(board[r*8+c]-1)]=@intCast(r*8+c);for(0..64)|i|put(output,i,path[i]);return 512;}
